const normalize = (value) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();

const hash32 = (text, seed) => {
  let hash = seed >>> 0;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};

const makeFingerprint = (text) =>
  hash32(text, 2166136261) + hash32(text, 2246822519);

const finalStatuses = new Set([
  'demand_analyzed',
  'classified_non_client',
]);

const output = [];

for (const item of $input.all()) {
  const j = item.json;

  const canonical = [
    j['title (Назва проєкту або вакансії)'],
    j['description (Опис)'],
    j['url (Посилання)'],
    j['published_at (Дата публікації)'],
    j['budget_min (Мінімальний бюджет)'],
    j['budget_max (Максимальний бюджет)'],
    j['currency (Валюта)'],
  ].map(normalize).join('\u001f');

  const currentFingerprint = makeFingerprint(canonical);
  const previousFingerprint = normalize(
    j['demand_source_fingerprint (Відбиток AI Demand)']
  );
  const previousStatus = normalize(
    j['demand_analysis_status (Статус AI Demand)']
  );

  const isNew = !previousFingerprint;
  const isChanged = !!previousFingerprint && previousFingerprint !== currentFingerprint;
  const isIncomplete = !finalStatuses.has(previousStatus);

  if (isNew || isChanged || isIncomplete) {
    output.push({
      json: {
        ...j,
        source_fingerprint: currentFingerprint,
        previous_demand_status: previousStatus,
        demand_change_type: isNew ? 'new' : (isChanged ? 'changed' : 'retry'),
      },
      pairedItem: item.pairedItem,
    });
  }
}

return output;

